<script setup lang="ts">
import {computed,onBeforeUnmount,ref} from 'vue';
import AppDialog from './AppDialog.vue';
type Values={limite_hora:number|null;duracao_segundos:number|null;volume_mib:number|null};
type Limits={configurados:Values;tetos:Record<keyof Values,number>;efetivos:Record<keyof Values,number>};
const props=defineProps<{canManage:boolean;request:<T>(path:string,method?:string,body?:unknown,signal?:AbortSignal)=>Promise<T>}>();
const fields=[{key:'limite_hora',label:'Execuções por hora',min:1},{key:'duracao_segundos',label:'Duração por execução (segundos)',min:10},{key:'volume_mib',label:'Volume por execução (MiB)',min:1}] as const;
const open=ref(false),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),limits=ref<Limits|null>(null),draft=ref<Record<keyof Values,string>>({limite_hora:'',duracao_segundos:'',volume_mib:''});
let alive=true,generation=0,controller:AbortController|undefined;
const issue=computed(()=>fields.some(field=>draft.value[field.key]!==''&&(!Number.isInteger(Number(draft.value[field.key]))||Number(draft.value[field.key])<field.min||Number(draft.value[field.key])>(limits.value?.tetos[field.key]??0)))?'Informe números inteiros dentro dos limites indicados, ou deixe em branco para herdar.':'');
async function load(){const current=++generation;controller?.abort();controller=new AbortController();loading.value=true;error.value='';limits.value=null;try{const result=await props.request<Limits>('/api/contexto/limites-monitoramento','GET',undefined,controller.signal);if(!alive||current!==generation)return;limits.value=result;for(const field of fields)draft.value[field.key]=result.configurados[field.key]===null?'':String(result.configurados[field.key]);}catch(cause){if(alive&&current===generation)error.value=(cause as Error).message;}finally{if(alive&&current===generation)loading.value=false;}}
function close(){if(busy.value)return;open.value=false;generation++;controller?.abort();}
async function save(){if(!props.canManage||!limits.value||busy.value||issue.value)return;busy.value=true;error.value='';notice.value='';const current=generation;try{const body=Object.fromEntries(fields.map(field=>[field.key,draft.value[field.key]===''?null:Number(draft.value[field.key])]));await props.request('/api/contexto/limites-monitoramento','PUT',body);if(!alive||current!==generation)return;notice.value='Limites salvos. Aplicados às próximas reservas de execução.';await load();}catch(cause){if(alive&&current===generation)error.value=(cause as Error).message;}finally{if(alive)busy.value=false;}}
onBeforeUnmount(()=>{alive=false;generation++;controller?.abort();});
</script>
<template><button type="button" class="secondary" @click="open=true;notice='';load()">Limites de coleta</button><AppDialog v-if="open" title="Limites de coleta" :busy="busy" @close="close"><p>Os tetos da plataforma limitam os valores efetivos. Deixe um campo em branco para herdar o teto. Execuções já reservadas mantêm os limites recebidos.</p><p v-if="loading" role="status">Carregando limites…</p><p v-if="notice" role="status">{{ notice }}</p><p v-if="error" role="alert">{{ error }}</p><button v-if="!limits&&!loading" type="button" class="secondary" @click="load">Tentar novamente</button><template v-if="limits"><div class="registry-scroll"><table><caption>Limites atuais do escritório</caption><thead><tr><th>Limite</th><th>Configurado</th><th>Teto da plataforma</th><th>Efetivo</th></tr></thead><tbody><tr v-for="field in fields" :key="field.key"><th scope="row">{{ field.label }}</th><td>{{ limits.configurados[field.key]??'Herdado' }}</td><td>{{ limits.tetos[field.key] }}</td><td>{{ limits.efetivos[field.key] }}</td></tr></tbody></table></div><form v-if="canManage" class="vue-form" @submit.prevent="save"><fieldset :disabled="busy" class="limits-fields"><legend>Configurar limites do escritório</legend><label v-for="field in fields" :key="field.key">{{ field.label }}<input :aria-label="field.label" v-model="draft[field.key]" type="number" :min="field.min" :max="limits.tetos[field.key]" step="1"><span>De {{ field.min }} a {{ limits.tetos[field.key] }}; em branco: herdado.</span></label></fieldset><p v-if="issue" role="alert">{{ issue }}</p><button type="submit" class="primary" :disabled="busy||!!issue">{{ busy?'Salvando…':'Salvar limites' }}</button></form><p v-else>Seu perfil permite consultar os limites. A configuração exige administração do escritório.</p></template></AppDialog></template>
<style scoped>.limits-fields{display:grid;gap:16px;min-width:0;border:0;padding:0}.limits-fields label{display:grid;gap:6px}.limits-fields span{font-size:.875rem}</style>
